export function getDemandReportData(
  medium: string,
  rawClassLabel: string | number,
): { titleHeaders: string[]; rows: BlockDemandRow[] } {
  let classLabel = String(rawClassLabel ?? "Class 9");
  if (!classLabel.startsWith("Class ")) {
    const num = classLabel.replace(/\D/g, "");
    classLabel = num ? `Class ${num}` : "Class 9";
  }

  const medData = DEMAND_REPORT_DATASET[medium];
  if (
    medData &&
    medData[classLabel] &&
    medData[classLabel].titleHeaders.length > 0
  ) {
    return medData[classLabel];
  }

  // Default fallback if medium/class combo is requested
  const titles = [
    `Textbook A (${classLabel})`,
    `Textbook B (${classLabel})`,
    `Textbook C (${classLabel})`,
  ];

  const defaultBaseBlocks = [
    {
      sno: 1,
      district: "AGAR MALWA",
      block: "AGAR",
      bcode: "235108",
    },
    {
      sno: 2,
      district: "PANNA",
      block: "AJAIGARH",
      bcode: "231001",
    },
    {
      sno: 3,
      district: "ALIRAJPUR",
      block: "ALIRAJPUR",
      bcode: "234902",
    },
    {
      sno: 4,
      district: "RATLAM",
      block: "ALOT",
      bcode: "232001",
    },
    {
      sno: 5,
      district: "SATNA",
      block: "AMARPATAN",
      bcode: "231301",
    },
    {
      sno: 6,
      district: "DINDORI",
      block: "AMARPUR",
      bcode: "234108",
    },
    {
      sno: 7,
      district: "CHHINDWARA",
      block: "AMARWADA",
      bcode: "234309",
    },
    {
      sno: 8,
      district: "MORENA",
      block: "AMBAH",
      bcode: "230202",
    },
    {
      sno: 9,
      district: "BETUL",
      block: "AMLA",
      bcode: "233501",
    },
    {
      sno: 10,
      district: "ANUPPUR",
      block: "ANUPPUR",
      bcode: "234701",
    },
    {
      sno: 11,
      district: "GUNA",
      block: "ARON",
      bcode: "230701",
    },
    {
      sno: 12,
      district: "ASHOKNAGAR",
      block: "ASHOKNAGAR",
      bcode: "234602",
    },
    {
      sno: 13,
      district: "SEHORE",
      block: "ASHTA",
      bcode: "233301",
    },
    {
      sno: 14,
      district: "BHIND",
      block: "ATER",
      bcode: "230306",
    },
    {
      sno: 15,
      district: "BETUL",
      block: "ATHNER",
      bcode: "233502",
    },
  ];
  const rows: BlockDemandRow[] = defaultBaseBlocks.map((b, idx) => {
    const quantities: Record<string, number> = {};
    titles.forEach((t, tIdx) => {
      quantities[t] = Math.round((1200 + idx * 140 + tIdx * 85) / 10) * 10;
    });
    return {
      sno: b.sno,
      district: b.district,
      block: b.block,
      bcode: b.bcode,
      quantities,
    };
  });

  return { titleHeaders: titles, rows };
}
